import{_ as p,C as s,c as l,o,aa as e,G as n}from"./chunks/framework.Cn7WEiMX.js";const x=JSON.parse('{"title":"在 6.x 的 CentOS 上通过 Nginx 搭建 Dynmap 网页服务器","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/advanced-configuration/external-webserver-advanced/external-webserver-on-linux/nginx-on-centos-6-x.md","filePath":"wiki/Dynmap/advanced-configuration/external-webserver-advanced/external-webserver-on-linux/nginx-on-centos-6-x.md"}'),r={name:"wiki/Dynmap/advanced-configuration/external-webserver-advanced/external-webserver-on-linux/nginx-on-centos-6-x.md"};function h(c,a,d,k,g,E){const i=s("NolebaseGitContributors"),t=s("NolebaseGitChangelog");return o(),l("div",null,[a[0]||(a[0]=e(`<h1 id="在-6-x-的-centos-上通过-nginx-搭建-dynmap-网页服务器" tabindex="-1">在 6.x 的 CentOS 上通过 Nginx 搭建 Dynmap 网页服务器 <a class="header-anchor" href="#在-6-x-的-centos-上通过-nginx-搭建-dynmap-网页服务器" aria-label="Permalink to &quot;在 6.x 的 CentOS 上通过 Nginx 搭建 Dynmap 网页服务器&quot;">​</a></h1> <h2 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h2> <p>使用 Nginx（或者为此使用 Apache）而不是内置的“卡顿网页服务器”可以缓解游戏服务器和地图在高峰时期的压力。他如果你托管自己的网站（并因此用到了 80 端口），这也可以让你把地图放在诸如 <a href="http://map.example.com/" target="_blank" rel="noreferrer">http://map.example.com/</a> 的链接里，而不是像 <a href="http://map.example.com:8123/" target="_blank" rel="noreferrer">http://map.example.com:8123/</a> 这样多一个端口号。</p> <p>（设置 DNS 记录不在此教程的讲述范围里。）</p> <p>注意：本教程假设网页服务器与游戏服务器分离。在这个示例中我会以 192.168.1.2 指代游戏服务器，以 192.168.1.3 指代 Nginx 服务器。如果你选择将这两个服务器放在同一台机器上，那么只需将配置中的 192.168.1.2 切换为 127.0.0.1——但需要注意的是这可能不是最好的选择（如果使用代理功能可能会好一点？存疑）。</p> <h2 id="centos" tabindex="-1">CentOS <a class="header-anchor" href="#centos" aria-label="Permalink to &quot;CentOS&quot;">​</a></h2> <p>为什么要用 CentOS？我要在这里引用维基百科的一句话：“CentOS（<strong>C</strong>ommunity <strong>Ent</strong>erprise <strong>O</strong>perating <strong>S</strong>ystem）是 Linux 发行版之一，它是来自于 Red Hat Enterprise Linux（RHEL）依照开放源代码规定发布的源代码所编译而成。CentOS 的存在是为了提供一个免费的企业级计算平台。”<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p> <p>对于安装部分，我一般使用“最小”安装 ISO 文件，然后手动安装所需的其他内容。我更喜欢少装一些，然后在后面的使用过程中补齐缺失内容，而不是一开始的时候就装一大堆东西。镜像链接<a href="http://www.centos.org/modules/tinycontent/index.php?id=30" target="_blank" rel="noreferrer">在此</a>。<code>x86_64</code> 的最小 ISO 位于 <code>/6.X/isos/x86_64/CentOS-6.X-x86_64-minimal.iso</code>（请将 X 替换为最新版本，在写这篇文章时为 6.4。）</p> <p>安装 CentOS，别忘了在安装过程中设置网络，不然首次启动后你需要手动编辑 <code>/etc/sysconfig/network-scripts/ifcfg-eth0</code> 文件。在设置静态 IP 后，你还可以通过 DHCP 服务器再次设置（一般为路由）。此时你也许需要修改 SSHd，不过这是可选项。</p> <h2 id="安装-nginx、php-与-php-fpm" tabindex="-1">安装 Nginx、PHP 与 PHP-FPM <a class="header-anchor" href="#安装-nginx、php-与-php-fpm" aria-label="Permalink to &quot;安装 Nginx、PHP 与 PHP-FPM&quot;">​</a></h2> <p>按照这里的教程安装 nginx。如果你安装了 <code>x86_64</code> 的 CentOS，你需要（以 root 身份登录）输入如下命令：</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ivh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://mirror.yandex.ru/epel/6/x86_64/epel-release-6-7.noarch.rpm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Uvh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://rpms.famillecollet.com/enterprise/remi-release-6.rpm</span></span></code></pre></div><p>在“配置 Nginx”部分，我一般会使用 <code>/var/www/map.example.com/public_html</code> 和 <code>/var/www/map.example.com/logs</code>，你可以自行决定。</p> <p>注意：需要为缓存创建文件夹，例如 <code>/var/www/cache</code>，输入 <code>chown nginx:nginx /var/www/cache</code> 即可。</p> <h2 id="设置-网站" tabindex="-1">设置“网站” <a class="header-anchor" href="#设置-网站" aria-label="Permalink to &quot;设置“网站”&quot;">​</a></h2> <p>在你创建的 <code>/etc/nginx/sites-available/map.example.com</code> 文件中，将配置修改为如下内容：</p> <div class="language-apache vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">apache</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    proxy_cache_path  /var/www/cache levels=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> keys_zone=map:8m max_size=1g inactive=24h;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    server_name map.example.com;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    access_log /var/www/map.example.com/logs/access.log;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    error_log /var/www/map.example.com/logs/error.log;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    root /var/www/map.example.com/public_html;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    location / {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        proxy_pass                  http://[IP OF MINECRAFT SERVER]:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9999</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        proxy_set_header            Host $host;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        proxy_cache                 map;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        proxy_cache_key &quot;$host$uri&quot;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        proxy_cache_valid  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 302</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  60m;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        proxy_cache_valid  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">404</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      10m;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        proxy_cache_use_stale       error timeout invalid_header updating http_500 http_503 http_504;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        proxy_connect_timeout </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>将 <code>proxy_pass</code> 变量改为 Dynmap 网页服务器的端口与 IP。</p> <h2 id="完成" tabindex="-1">完成 <a class="header-anchor" href="#完成" aria-label="Permalink to &quot;完成&quot;">​</a></h2> <p>输入命令 <code>service nginx reload</code> 重载配置。</p> <p>确保端口 80 在防火墙中开放（<code>iptables</code>），nginx 服务器的公开 IP 有与 <code>map.exmaple.com</code> 域名关联的 DNS A 记录。</p> <p>现在，打开 <a href="http://map.example.com" target="_blank" rel="noreferrer">http://map.example.com</a> 即可看到你的网页地图。</p> `,42)),n(i),n(t),a[1]||(a[1]=e('<hr class="footnotes-sep"> <section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>引用日期：2026/7/20。此句后半句原文并没有在维基百科的 CentOS 页面上找到。 <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',3))])}const _=p(r,[["render",h]]);export{x as __pageData,_ as default};
